-- =====================================================================
-- «Қазақ хандығы: Хан тағы» · GAME HUB · Supabase схемасы (толық)
-- Supabase → SQL Editor → New query → осы файлды толық қойып → Run
-- Қайта іске қосуға болады (idempotent).
-- =====================================================================

-- ---------- 1. Профильдер ----------
create table if not exists public.profiles (
  id            uuid primary key references auth.users(id) on delete cascade,
  email         text,
  full_name     text not null default 'Студент',
  display_name  text,
  avatar_url    text,
  is_admin      boolean not null default false,
  games_played  integer not null default 0,
  total_score   integer not null default 0,
  correct_total integer not null default 0,
  wrong_total   integer not null default 0,
  play_seconds  integer not null default 0,
  created_at    timestamptz not null default now(),
  -- input validation дерекқор деңгейінде
  constraint display_name_ok check (
    display_name is null or display_name ~ '^[[:alnum:][:space:].-]{2,30}$'
  )
);

-- Жаңа Google қолданушысы кірген кезде профиль автоматты жасалады
create or replace function public.handle_new_user()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  begin
    insert into public.profiles (id, email, full_name, avatar_url)
    values (
      new.id, new.email,
      left(coalesce(new.raw_user_meta_data->>'full_name', new.raw_user_meta_data->>'name', split_part(new.email, '@', 1), 'Студент'), 60),
      new.raw_user_meta_data->>'avatar_url'
    )
    on conflict (id) do nothing;
  exception when others then
    -- профиль жасалмаса да кіру бұзылмайды; профильді khan-start функциясы жасайды
    raise warning 'profile create failed: %', sqlerrm;
  end;
  return new;
end $$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- Админ екенін тексеретін көмекші функция (RLS ішінде қолданылады)
create or replace function public.is_admin()
returns boolean language sql stable security definer set search_path = public as $$
  select coalesce((select is_admin from public.profiles where id = auth.uid()), false);
$$;

-- ---------- 5. Рейтинг ----------
create table if not exists public.leaderboard (
  user_id     uuid not null references public.profiles(id) on delete cascade,
  game        text not null default 'khan-tagy',
  full_name   text not null,
  best_score  integer not null default 0,
  best_level  integer not null default 0,
  updated_at  timestamptz not null default now(),
  primary key (user_id, game)
);

-- =====================================================================
-- ROW LEVEL SECURITY — әр кестеде қосулы
-- Edge Functions secret key арқылы жазады (RLS-ті тек сервер айналып өтеді)
-- =====================================================================
alter table public.profiles     enable row level security;
alter table public.leaderboard  enable row level security;

-- Профиль: өзін көреді; админ бәрін көреді
drop policy if exists profiles_select on public.profiles;
create policy profiles_select on public.profiles
  for select to authenticated
  using (id = auth.uid() or public.is_admin());

-- Профиль: тек өз display_name өрісін өзгерте алады (бағандық құқық төменде)
drop policy if exists profiles_update_own on public.profiles;
create policy profiles_update_own on public.profiles
  for update to authenticated
  using (id = auth.uid()) with check (id = auth.uid());

revoke update on public.profiles from authenticated, anon;
grant  update (display_name) on public.profiles to authenticated;

-- Рейтинг: кірген әр студент оқи алады; insert/update саясаты ЖОҚ
drop policy if exists leaderboard_read on public.leaderboard;
create policy leaderboard_read on public.leaderboard
  for select to authenticated using (true);

-- Клиент рөлдеріне жазу құқығын толық алып тастау (қосымша қорғаныс қабаты)
revoke insert, update, delete on public.leaderboard from authenticated, anon;

-- ---------- 6. Админ журналы (кіру әрекеттері + тазалау) ----------
-- Тек admin-panel функциясы жазады/оқиды. Клиентке толық жабық (RLS қосулы, саясат жоқ).
create table if not exists public.admin_log (
  id         bigint generated always as identity primary key,
  user_id    uuid references auth.users(id) on delete set null,
  action     text not null,
  created_at timestamptz not null default now()
);
create index if not exists admin_log_user_time on public.admin_log(user_id, action, created_at desc);
alter table public.admin_log enable row level security;
revoke all on public.admin_log from authenticated, anon;

-- ---------- 7. Хан тағы: сұрақтар (дұрыс жауап answer бағанында — клиентке жабық) ----------
create table if not exists public.khan_questions (
  id         text primary key,
  stage      integer not null check (stage between 1 and 10),
  type       text not null check (type in ('single','fill','order','match','map','image')),
  prompt     text not null,
  data       jsonb not null default '{}'::jsonb,
  answer     jsonb not null,
  difficulty integer not null default 1,
  active     boolean not null default true
);

-- ---------- 8. Ойын сессиялары (әр кезең — бір сессия) ----------
create table if not exists public.khan_games (
  id             uuid primary key default gen_random_uuid(),
  user_id        uuid not null references public.profiles(id) on delete cascade,
  stage          integer not null check (stage between 1 and 10),
  khan_idx       integer not null check (khan_idx between 0 and 9),
  status         text not null default 'active' check (status in ('active','won','lost','abandoned')),
  question_ids   text[] not null,
  started_at     timestamptz not null default now(),
  finished_at    timestamptz,
  correct        integer not null default 0,
  wrong          integer not null default 0,
  med_used       integer not null default 0,
  kills          integer not null default 0,
  lives_left     integer not null default 0,
  waves          integer not null default 0,
  bars           jsonb,
  client_time_ms integer,
  score          integer not null default 0
);
create index if not exists khan_games_user_started on public.khan_games(user_id, started_at desc);

-- ---------- 9. Жауаптар журналы ----------
create table if not exists public.khan_answers (
  id          bigint generated always as identity primary key,
  game_id     uuid not null references public.khan_games(id) on delete cascade,
  user_id     uuid not null references public.profiles(id) on delete cascade,
  question_id text not null references public.khan_questions(id),
  kind        text not null check (kind in ('decision','med')),
  slot        integer,
  correct     boolean not null,
  created_at  timestamptz not null default now()
);
create index if not exists khan_answers_user_time on public.khan_answers(user_id, created_at desc);
create index if not exists khan_answers_game on public.khan_answers(game_id);

-- ---------- RLS: тек өз деректерін оқиды, жазуды тек Edge Functions жасайды ----------
alter table public.khan_questions enable row level security;
alter table public.khan_games     enable row level security;
alter table public.khan_answers   enable row level security;

drop policy if exists khan_games_select on public.khan_games;
create policy khan_games_select on public.khan_games
  for select to authenticated using (user_id = auth.uid() or public.is_admin());
drop policy if exists khan_answers_select on public.khan_answers;
create policy khan_answers_select on public.khan_answers
  for select to authenticated using (user_id = auth.uid() or public.is_admin());
drop policy if exists khan_questions_admin on public.khan_questions;
create policy khan_questions_admin on public.khan_questions
  for select to authenticated using (public.is_admin());

revoke insert, update, delete on public.khan_questions, public.khan_games, public.khan_answers from authenticated, anon;
revoke all on public.khan_questions from anon;

